#### **Langkah 3: Filter Menu Sidebar Berdasarkan Role User**
Di [AppSidebarNav.js](file:///f:/magang/feeder/frontend/src/components/AppSidebarNav.js), ambil data user dari `sessionStorage` dan filter item menu sebelum dirender:
```javascript
setup() {
  const route = useRoute()
  const firstRender = ref(true)

  // Ambil data user dari sessionStorage
  const user = JSON.parse(sessionStorage.getItem('user') || '{}')
  const userRole = user.jenis_akun // atau field role/jenis_akun dari backend

  onMounted(() => {
    firstRender.value = false
  })

  // Filter menu berdasarkan role user
  const filteredNav = nav.filter(item => {
    if (!item.roles) return true // Jika tidak butuh role khusus, tampilkan
    return item.roles.includes(userRole) // Jika butuh, cek apakah role user cocok
  })

  // ... (gunakan filteredNav untuk me-map renderItem)
  return () =>
    h(
      CSidebarNav,
      {},
      {
        default: () => filteredNav.map((item) => renderItem(item)),
      },
    )
}
```

#### **Langkah 4: Proteksi Route via Router Guard**
Agar user biasa tidak bisa mengetik URL secara manual (misal bypass langsung ke `/sistem/data-pengguna`), tambahkan meta field di [index.js](file:///f:/magang/feeder/frontend/src/router/index.js):
```javascript
{
  path: '/sistem/data-pengguna',
  name: 'Data Pengguna',
  component: () => import('@/views/sistem/dataPengguna.vue'),
  meta: { roles: ['superadmin'] }
}
```
Lalu tambahkan `router.beforeEach` untuk memeriksa hak akses sebelum route berpindah:
```javascript
router.beforeEach((to, from, next) => {
  const token = sessionStorage.getItem('token')
  const user = JSON.parse(sessionStorage.getItem('user') || '{}')
  const userRole = user.jenis_akun

  if (to.matched.some(record => record.meta.roles)) {
    const requiredRoles = to.meta.roles
    if (token && requiredRoles.includes(userRole)) {
      next()
    } else {
      next('/dashboard') // Redirect jika tidak berhak
    }
  } else {
    next()
  }
})
```

